import pandas as pd

def find_cities(cities: pd.DataFrame) -> pd.DataFrame:
    if cities.empty:
        return pd.DataFrame(columns=['state', 'cities'])
    res = cities.groupby('state')['city'].apply(lambda x: ', '.join(sorted(x))).reset_index(name='cities')
    return res.sort_values(by='state').reset_index(drop=True)
